1	// Command indexroom is the 链上索引与交易分析服务 entry point.
2	package main
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"strings"
10	
11		"github.com/gzhysuiioo/indexroom-analytics/indexroom"
12	)
13	
14	func main() {
15		command := "demo"
16		if len(os.Args) > 1 {
17			command = os.Args[1]
18		}
19		switch command {
20		case "demo":
21			runDemo()
22		case "version":
23			fmt.Println("indexroom 0.1.0")
24		case "register":
25			os.Exit(runRegister())
26		case "help", "-h", "--help":
27			usage()
28		default:
29			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
30			usage()
31			os.Exit(2)
32		}
33	}
34	
35	func usage() {
36		fmt.Println("usage: indexroom [demo|version|register|help]")
37		fmt.Println()
38		fmt.Println("register reads requests as JSON from standard input and maintains an")
39		fmt.Println("in-memory service instance registry with offline health observations:")
40		fmt.Println(`  {"requests":[{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"host:8080"}]},`)
41		fmt.Println(`              {"type":"health","service":"svc","instanceId":"i1","expectedRevision":1,"sequence":1,"healthy":true},`)
42		fmt.Println(`              {"type":"select","service":"svc","expectedRevision":1}]}`)
43		fmt.Println("A register request fully replaces the service's instance list; new services")
44		fmt.Println("require expectedRevision 0, existing services the current revision. A health")
45		fmt.Println("request records an offline observation (healthy/unhealthy) for one instance;")
46		fmt.Println("it never probes. Health updates never bump the registration revision. A")
47		fmt.Println("select request chooses one healthy instance, rotating per service by ascending")
48		fmt.Println("instance id; it performs no network access and never changes revisions or")
49		fmt.Println("health records, and reports invalid/conflict/not_found/no_healthy on failure.")
50		fmt.Println("A select request may carry an optional \"sessionKey\" string: requests in the")
51		fmt.Println("same service with the same trimmed key reuse the instance first chosen for")
52		fmt.Println("that key while it stays registered and healthy, without moving the rotation.")
53		fmt.Println("Exit status is 0 only when every request succeeds.")
54	}
55	
56	// registerInstance is one instance in the final service list.
57	type registerInstance struct {
58		ID       string `json:"id"`
59		Address  string `json:"address"`
60		Health   string `json:"health"`
61		Sequence int64  `json:"sequence"`
62		Reason   string `json:"reason,omitempty"`
63	}
64	
65	// registerService is one service in the final service list.
66	type registerService struct {
67		Service   string             `json:"service"`
68		Revision  int                `json:"revision"`
69		Instances []registerInstance `json:"instances"`
70	}
71	
72	// registerResult is the per-item outcome.
73	type registerResult struct {
74		Service          string `json:"service"`
75		OK               bool   `json:"ok"`
76		Changed          bool   `json:"changed,omitempty"`
77		Revision         int    `json:"revision"`
78		Error            string `json:"error,omitempty"`
79		Reason           string `json:"reason,omitempty"`
80		ExpectedRevision int    `json:"expectedRevision,omitempty"`
81		ActualRevision   int    `json:"actualRevision,omitempty"`
82		Sequence         int64  `json:"sequence,omitempty"`
83		InstanceID       string `json:"instanceId,omitempty"`
84		Address          string `json:"address,omitempty"`
85	}
86	
87	// registerOutput is the full register output.
88	type registerOutput struct {
89		Results  []registerResult  `json:"results"`
90		Services []registerService `json:"services"`
91	}
92	
93	// runRegister processes registration requests from standard input.
94	// It returns the process exit code: 0 when all registrations succeed, 1 otherwise.
95	func runRegister() int {
96		data, err := io.ReadAll(os.Stdin)
97		if err != nil {
98			return failRegister(fmt.Sprintf("could not read standard input: %v", err))
99		}
100	
101		var top struct {
102			Requests json.RawMessage `json:"requests"`
103		}
104		if err := json.Unmarshal(data, &top); err != nil {
105			return failRegister(fmt.Sprintf("input must be a JSON object with a requests array: %v", err))
106		}
107		if len(top.Requests) == 0 || strings.TrimSpace(string(top.Requests)) == "null" {
108			return failRegister("input must contain a \"requests\" array")
109		}
110		var rawRequests []json.RawMessage
111		if err := json.Unmarshal(top.Requests, &rawRequests); err != nil {
112			return failRegister("\"requests\" must be a JSON array")
113		}
114	
115		proc := &registerProcessor{
116			registry: indexroom.NewRegistry(),
117			results:  make([]registerResult, 0, len(rawRequests)),
118		}
119	
120		for _, raw := range rawRequests {
121			var head struct {
122				Service string          `json:"service"`
123				Type    json.RawMessage `json:"type"`
124			}
125			_ = json.Unmarshal(raw, &head)
126			service := strings.TrimSpace(head.Service)
127	
128			reqType := "register"
129			if len(head.Type) > 0 && strings.TrimSpace(string(head.Type)) != "null" {
130				var t string
131				if err := json.Unmarshal(head.Type, &t); err != nil {
132					proc.invalid(service, "type must be a string")
133					continue
134				}
135				reqType = t
136			}
137	
138			switch reqType {
139			case "", "register":
140				proc.registerRequest(raw, service)
141			case "health":
142				proc.healthRequest(raw, service)
143			case "select":
144				proc.selectRequest(raw, service)
145			default:
146				proc.invalidf(service, "unknown type %q", reqType)
147			}
148		}
149	
150		results, anyFailed := proc.results, proc.failed
151		registry := proc.registry
152	
153		services := make([]registerService, 0)
154		for _, view := range registry.Snapshot() {
155			insts := make([]registerInstance, 0, len(view.Instances))
156			for _, inst := range view.Instances {
157				insts = append(insts, registerInstance{
158					ID:       inst.ID,
159					Address:  inst.Address,
160					Health:   string(inst.Health),
161					Sequence: inst.Sequence,
162					Reason:   inst.Reason,
163				})
164			}
165			services = append(services, registerService{
166				Service:   view.Service,
167				Revision:  view.Revision,
168				Instances: insts,
169			})
170		}
171	
172		writeRegisterOutput(registerOutput{Results: results, Services: services})
173		if anyFailed {
174			return 1
175		}
176		return 0
177	}
178	
179	// registerProcessor runs the request batch in input order. Failed items keep
180	// their slot in results and set failed; later items still run against the
181	// state committed by earlier successful items.
182	type registerProcessor struct {
183		registry *indexroom.Registry
184		results  []registerResult
185		failed   bool
186	}
187	
188	// invalid records an input-validation failure for an item. Content validity is
189	// checked before any business rule, so the revision stamped here is the
190	// service's current revision when the item is handled.
191	func (p *registerProcessor) invalid(service, reason string) {
192		p.failed = true
193		p.results = append(p.results, registerResult{
194			Service:  service,
195			OK:       false,
196			Error:    "invalid",
197			Reason:   reason,
198			Revision: p.registry.RevisionOf(service),
199		})
200	}
201	
202	// invalidf is invalid with a formatted reason.
203	func (p *registerProcessor) invalidf(service, format string, args ...any) {
204		p.invalid(service, fmt.Sprintf(format, args...))
205	}
206	
207	// reject records a business-rule failure (conflict, not_found, stale or
208	// no_healthy), keeping each operation's distinct result fields. Health
209	// rejections additionally carry the current sequence; register and select
210	// pass 0 so it stays omitted.
211	func (p *registerProcessor) reject(service string, kind indexroom.OutcomeKind, reason string, revision, expected, actual int, sequence int64) {
212		p.failed = true
213		p.results = append(p.results, registerResult{
214			Service:          service,
215			OK:               false,
216			Error:            string(kind),
217			Reason:           reason,
218			Revision:         revision,
219			ExpectedRevision: expected,
220			ActualRevision:   actual,
221			Sequence:         sequence,
222		})
223	}
224	
225	// succeed records an accepted item; omitempty keeps zero-valued fields out of
226	// the output exactly as before the refactor.
227	func (p *registerProcessor) succeed(result registerResult) {
228		result.OK = true
229		p.results = append(p.results, result)
230	}
231	
232	// registerRequest processes one register request, appending its outcome.
233	func (p *registerProcessor) registerRequest(raw json.RawMessage, service string) {
234		var req struct {
235			Service   string          `json:"service"`
236			Revision  *int64          `json:"expectedRevision"`
237			Instances json.RawMessage `json:"instances"`
238		}
239		if err := json.Unmarshal(raw, &req); err != nil {
240			p.invalidf(service, "request must be an object with service, expectedRevision and instances: %v", err)
241			return
242		}
243		service = strings.TrimSpace(req.Service)
244	
245		if req.Revision == nil {
246			p.invalid(service, "expectedRevision is required and must be a non-negative integer")
247			return
248		}
249		if !isJSONArray(req.Instances) {
250			p.invalid(service, "instances must be an array")
251			return
252		}
253		var instances []indexroom.Instance
254		if err := json.Unmarshal(req.Instances, &instances); err != nil {
255			p.invalidf(service, "instances must be an array of objects with id and address: %v", err)
256			return
257		}
258	
259		registration, err := p.registry.ValidateRegistration(service, int(*req.Revision), instances)
260		if err != nil {
261			p.invalid(service, err.Error())
262			return
263		}
264	
265		outcome := p.registry.Apply(registration)
266		if !outcome.OK {
267			p.reject(outcome.Service, outcome.Kind, outcome.Reason, outcome.Revision, outcome.Expected, outcome.Actual, 0)
268			return
269		}
270		p.succeed(registerResult{
271			Service:  outcome.Service,
272			Changed:  outcome.Changed,
273			Revision: outcome.Revision,
274		})
275	}
276	
277	// healthRequest processes one health observation request, appending its outcome.
278	func (p *registerProcessor) healthRequest(raw json.RawMessage, service string) {
279		var req struct {
280			Service    string  `json:"service"`
281			InstanceID string  `json:"instanceId"`
282			Revision   *int64  `json:"expectedRevision"`
283			Sequence   *int64  `json:"sequence"`
284			Healthy    *bool   `json:"healthy"`
285			Reason     *string `json:"reason"`
286		}
287		if err := json.Unmarshal(raw, &req); err != nil {
288			p.invalidf(service, "health request must be an object with service, instanceId, expectedRevision, sequence and healthy: %v", err)
289			return
290		}
291		service = strings.TrimSpace(req.Service)
292	
293		if req.Revision == nil {
294			p.invalid(service, "expectedRevision is required and must be a non-negative integer")
295			return
296		}
297		if req.Sequence == nil {
298			p.invalid(service, "sequence is required and must be a positive integer")
299			return
300		}
301		if req.Healthy == nil {
302			p.invalid(service, "healthy is required and must be a boolean")
303			return
304		}
305		reason := ""
306		if req.Reason != nil {
307			reason = *req.Reason
308		}
309	
310		update, err := p.registry.ValidateHealth(service, req.InstanceID, int(*req.Revision), *req.Sequence, *req.Healthy, reason)
311		if err != nil {
312			p.invalid(service, err.Error())
313			return
314		}
315	
316		outcome := p.registry.ApplyHealth(update)
317		if !outcome.OK {
318			p.reject(outcome.Service, outcome.Kind, outcome.Reason, outcome.Revision, outcome.Expected, outcome.Actual, outcome.Sequence)
319			return
320		}
321		p.succeed(registerResult{
322			Service:  outcome.Service,
323			Changed:  outcome.Changed,
324			Revision: outcome.Revision,
325			Sequence: outcome.Sequence,
326		})
327	}
328	
329	// selectRequest processes one select request, appending its outcome.
330	// A selection performs no network access and never alters registrations or
331	// health records; it only advances the service's healthy-instance rotation
332	// and, for requests carrying a sessionKey, maintains that session's binding.
333	func (p *registerProcessor) selectRequest(raw json.RawMessage, service string) {
334		var req struct {
335			Service  string          `json:"service"`
336			Revision *int64          `json:"expectedRevision"`
337			Session  json.RawMessage `json:"sessionKey"`
338		}
339		if err := json.Unmarshal(raw, &req); err != nil {
340			p.invalidf(service, "select request must be an object with service and expectedRevision: %v", err)
341			return
342		}
343		service = strings.TrimSpace(req.Service)
344	
345		if req.Revision == nil {
346			p.invalid(service, "expectedRevision is required and must be a non-negative integer")
347			return
348		}
349	
350		// sessionKey is optional: absent means an ordinary rotating selection. An
351		// explicitly provided null, a non-string value or a blank string is
352		// invalid; the registry trims the key and treats keys equal after trimming
353		// as the same session.
354		var sessionKey *string
355		if len(req.Session) > 0 {
356			if strings.TrimSpace(string(req.Session)) == "null" {
357				p.invalid(service, "sessionKey must be a string, not null")
358				return
359			}
360			var key string
361			if err := json.Unmarshal(req.Session, &key); err != nil {
362				p.invalid(service, "sessionKey must be a string")
363				return
364			}
365			sessionKey = &key
366		}
367	
368		selection, err := p.registry.ValidateSelectionWithSession(service, int(*req.Revision), sessionKey)
369		if err != nil {
370			p.invalid(service, err.Error())
371			return
372		}
373	
374		outcome := p.registry.Select(selection)
375		if !outcome.OK {
376			p.reject(outcome.Service, outcome.Kind, outcome.Reason, outcome.Revision, outcome.Expected, outcome.Actual, 0)
377			return
378		}
379		p.succeed(registerResult{
380			Service:    outcome.Service,
381			Revision:   outcome.Revision,
382			InstanceID: outcome.InstanceID,
383			Address:    outcome.Address,
384			Sequence:   outcome.Sequence,
385		})
386	}
387	
388	// failRegister emits a top-level input error and returns exit code 1.
389	func failRegister(reason string) int {
390		writeRegisterOutput(struct {
391			Error string `json:"error"`
392		}{Error: reason})
393		return 1
394	}
395	
396	func writeRegisterOutput(v any) {
397		enc := json.NewEncoder(os.Stdout)
398		enc.SetIndent("", "  ")
399		_ = enc.Encode(v)
400	}
401	
402	// isJSONArray reports whether raw is a JSON array (ignoring leading whitespace).
403	func isJSONArray(raw json.RawMessage) bool {
404		for _, b := range raw {
405			switch b {
406			case ' ', '\t', '\n', '\r':
407				continue
408			case '[':
409				return true
410			default:
411				return false
412			}
413		}
414		return false
415	}
416	
417	func runDemo() {
418		index := indexroom.New()
419		blocks := []indexroom.Block{
420			{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"t1", "t2"}},
421			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"t3"}},
422		}
423		for _, block := range blocks {
424			if err := index.Append(block); err != nil {
425				fmt.Printf("append refused at height %d: %v\n", block.Height, err)
426				continue
427			}
428			fmt.Printf("indexed height=%d txs=%d\n", block.Height, len(block.Txs))
429		}
430		if err := index.Append(indexroom.Block{Height: 3, Hash: "h3", Parent: "h1"}); err != nil {
431			fmt.Println("non-linear block refused:", err)
432		}
433		dropped, err := index.Reorg([]indexroom.Block{{Height: 2, Hash: "h2b", Parent: "h1", Txs: []string{"t4", "t5"}}})
434		fmt.Printf("reorg dropped=%v err=%v tip=%d\n", dropped, err, index.Tip)
435	}
