606	func TestSelectAddressReplacementKeepsRotation(t *testing.T) {
607		// One instance keeps its id but gets a new address: the registration bumps
608		// once, that instance resets to unknown/0 while untouched instances keep
609		// their observations, and the rotation continues after the last chosen id
610		// instead of restarting at the smallest id.
611		input := `{"requests":[
612			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"},{"id":"d","address":"h4:4"}]},
613			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":11,"healthy":true},
614			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":12,"healthy":true},
615			{"type":"health","service":"svc","instanceId":"c","expectedRevision":1,"sequence":13,"healthy":true},
616			{"type":"health","service":"svc","instanceId":"d","expectedRevision":1,"sequence":14,"healthy":false,"reason":"connection refused"},
617			{"type":"select","service":"svc","expectedRevision":1},
618			{"type":"select","service":"svc","expectedRevision":1},
619			{"type":"register","service":"svc","expectedRevision":1,"instances":[{"id":"a","address":"h9:9"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"},{"id":"d","address":"h4:4"}]},
620			{"type":"select","service":"svc","expectedRevision":2},
621			{"type":"select","service":"svc","expectedRevision":2}
622		]}`
623		out, code := runRegisterWith(t, input)
624		if code != 0 {
625			t.Fatalf("exit code: %d, output: %s", code, out)
626		}
627		var got registerOutput
628		if err := json.Unmarshal([]byte(out), &got); err != nil {
629			t.Fatalf("output is not JSON: %v\n%s", err, out)
630		}
631		if len(got.Results) != 10 {
632			t.Fatalf("results: %+v", got.Results)
633		}
634		// Rotation before the replacement: a then b, cursor rests on b.
635		if r := got.Results[5]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 11 {
636			t.Fatalf("first select: %+v", r)
637		}
638		if r := got.Results[6]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 12 {
639			t.Fatalf("second select: %+v", r)
640		}
641		// The address-only replacement succeeds and bumps the revision exactly once.
642		if r := got.Results[7]; !r.OK || !r.Changed || r.Revision != 2 {
643			t.Fatalf("address replacement: %+v", r)
644		}
645		// The new address of a has no observation yet, so it is skipped; the
646		// rotation continues just after b and lands on c, never on a's old address.
647		if r := got.Results[8]; !r.OK || r.InstanceID != "c" || r.Address != "h3:3" || r.Sequence != 13 || r.Revision != 2 {
648			t.Fatalf("select after replacement should continue after b at c: %+v", r)
649		}
650		// Past the end the rotation wraps to the smallest eligible id (b), proving
651		// it did not restart from the smallest id because of the replacement.
652		if r := got.Results[9]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 12 || r.Revision != 2 {
653			t.Fatalf("select should wrap to smallest eligible id: %+v", r)
654		}
655		// Final state: a is unknown at sequence 0 with no leftover reason; the
656		// untouched instances keep their health, sequence and reason.
657		if len(got.Services) != 1 || got.Services[0].Revision != 2 {
658			t.Fatalf("services: %+v", got.Services)
659		}
660		insts := got.Services[0].Instances
661		if len(insts) != 4 {
662			t.Fatalf("instances: %+v", insts)
663		}
664		if insts[0].ID != "a" || insts[0].Address != "h9:9" || insts[0].Health != "unknown" || insts[0].Sequence != 0 || insts[0].Reason != "" {
665			t.Fatalf("replaced instance should reset to unknown/0: %+v", insts[0])
666		}
667		if insts[1].ID != "b" || insts[1].Health != "healthy" || insts[1].Sequence != 12 {
668			t.Fatalf("b should keep its observation: %+v", insts[1])
669		}
670		if insts[2].ID != "c" || insts[2].Health != "healthy" || insts[2].Sequence != 13 {
671			t.Fatalf("c should keep its observation: %+v", insts[2])
672		}
673		if insts[3].ID != "d" || insts[3].Health != "unhealthy" || insts[3].Sequence != 14 || insts[3].Reason != "connection refused" {
674			t.Fatalf("d should keep its observation and reason: %+v", insts[3])
675		}
676	}
