975	// TestRejectedReplacementKeepsAcceptedStateAndRotation is the regression guard
976	// for replacement requests against an existing service whose rotation is
977	// already in use: a rejected register must not partially replace instances,
978	// reset accepted health, consume a revision or move the selection position, and
979	// later selects in the same batch must keep using the previously accepted
980	// state. Two rejection conditions are exercised:
981	//
982	//   - a list with a valid prefix that changes an existing address followed by an
983	//     invalid instance address is invalid as a whole (field validation precedes
984	//     the revision check, so a simultaneously wrong expectedRevision still
985	//     reports invalid), and the valid prefix must not take effect;
986	//   - a fully valid list with a mismatched expectedRevision is a conflict
987	//     naming both revisions; no part of the replacement is applied.
988	func TestRejectedReplacementKeepsAcceptedStateAndRotation(t *testing.T) {
989		input := `{"requests":[
990			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"},{"id":"i2","address":"h2:8080"}]},
991			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":1,"sequence":11,"healthy":true},
992			{"type":"health","service":"svc","instanceId":"i2","expectedRevision":1,"sequence":22,"healthy":true},
993			{"type":"select","service":"svc","expectedRevision":1},
994			{"type":"register","service":"svc","expectedRevision":9,"instances":[{"id":"i1","address":"h9:8080"},{"id":"i2","address":"bad-address"}]},
995			{"type":"select","service":"svc","expectedRevision":1},
996			{"type":"register","service":"svc","expectedRevision":5,"instances":[{"id":"i1","address":"hx:8080"},{"id":"i2","address":"h2:8080"}]},
997			{"type":"select","service":"svc","expectedRevision":1}
998		]}`
999		out, code := runRegisterWith(t, input)
1000		if code != 1 {
1001			t.Fatalf("batch contains failures, exit code: %d, output: %s", code, out)
1002		}
1003		var got registerOutput
1004		if err := json.Unmarshal([]byte(out), &got); err != nil {
1005			t.Fatalf("output is not JSON: %v\n%s", err, out)
1006		}
1007		// The failed items keep their slots, in input order, with the later
1008		// successful selects still present; a later success does not cancel the
1009		// earlier failures.
1010		if len(got.Results) != 8 {
1011			t.Fatalf("results: %+v", got.Results)
1012		}
1013		// 0: accepted registration at revision 1.
1014		if r := got.Results[0]; !r.OK || !r.Changed || r.Revision != 1 {
1015			t.Fatalf("result 0: %+v", r)
1016		}
1017		// 1-2: both offline health observations accepted without a revision bump.
1018		if r := got.Results[1]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 11 {
1019			t.Fatalf("result 1: %+v", r)
1020		}
1021		if r := got.Results[2]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 22 {
1022			t.Fatalf("result 2: %+v", r)
1023		}
1024		// 3: first selection takes the smallest healthy id, cursor rests on i1.
1025		if r := got.Results[3]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" || r.Sequence != 11 || r.Revision != 1 {
1026			t.Fatalf("result 3: %+v", r)
1027		}
1028		// 4: the later instance address is invalid. The whole item is invalid even
1029		// though expectedRevision 9 is also wrong, because field validation precedes
1030		// the revision check; the reason names the bad address and no revision
1031		// comparison is reported. The valid prefix (i1's new address) must not be
1032		// applied either.
1033		if r := got.Results[4]; r.OK || r.Error != "invalid" || r.Revision != 1 ||
1034			r.ExpectedRevision != 0 || r.ActualRevision != 0 ||
1035			r.InstanceID != "" || r.Address != "" {
